━━━━━━━━━━━━━━━━━━━━━━
・建築物の所有者、管理者または占有者は、建築物の敷地、構造および建築設備を常時適法な状態に維持するよう努めなければならない★（努力義務）
・特殊建築物で安全上、防火上または衛生上特に重要であるものとして政令で定めるもの、および法6条1項1号・2号の建築物の所有者等は、必要に応じて維持保全に関する準則または計画を作成し、その他適切な措置を講じなければならない（法8条2項）

