・内容：建築物の敷地、位置、構造、用途、形態、意匠または建築設備に関する基準
・認可の公告のあった日以後にその土地の所有者等となった者にも効力が及ぶ★（承継効）
・一人協定：土地の所有者が一人しかいない場合でも協定を定めることができ、認可の日から3年以内に2以上の土地所有者等が存することとなったときから効力を生じる★
・変更は全員の合意、廃止は過半数の合意で足りる★

