        body: `▼ゼロから：階段は建物の中で最も事故が起きやすい場所です。だから建築基準法は用途と規模に応じて、階段の幅、蹴上げ、踏面を細かく定めています。令23条の表は法規のなかで最も出題頻度が高い表のひとつで、法令集を開けばそのまま答えが書いてあります。したがって覚えるべきは「どの行を見るか」の判断です。小中高の児童生徒用か、大きな物販店舗の客用か、規模の大きい階の直通階段か、その他か、住宅か。この五つの区分が読めれば表は引けます。加えて、踊場をどこに設けるか、手すりはどの階段に要るか、階段の幅をどう測るかという周辺のルールも押さえておきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 階段の寸法（令23条1項の表）
━━━━━━━━━━━━━━━━━━━━━━
・小学校、中学校、義務教育学校、高等学校、中等教育学校の児童・生徒用：幅140センチメートル以上、蹴上げ16センチメートル以下、踏面26センチメートル以上★（小学校の児童用は蹴上げ16センチメートル以下）
・劇場、映画館、公会堂、集会場等の客用、物品販売業を営む店舗（床面積の合計が1500平方メートルを超えるもの）の客用：幅140センチメートル以上、蹴上げ18センチメートル以下、踏面26センチメートル以上★
・直上階の居室の床面積の合計が200平方メートルを超える地上階、または居室の床面積の合計が100平方メートルを超える地階・地下工作物内におけるもの：幅120センチメートル以上、蹴上げ20センチメートル以下、踏面24センチメートル以上★
・その他：幅75センチメートル以上、蹴上げ22センチメートル以下、踏面21センチメートル以上★
・住宅（共同住宅の共用階段を除く）：幅75センチメートル以上、蹴上げ23センチメートル以下、踏面15センチメートル以上★

━━━━━━━━━━━━━━━━━━━━━━
🔑 幅の測り方と回り階段（令23条3項、令24条の関連）
━━━━━━━━━━━━━━━━━━━━━━
・階段および踊場の手すりならびに階段の昇降を安全に行うための設備で高さが50センチメートル以下のものについては、その幅が10センチメートルを限度として、ないものとみなして階段の幅を算定する★
・回り階段の部分における踏面の寸法は、踏面の狭いほうの端から30センチメートルの位置において測る★

━━━━━━━━━━━━━━━━━━━━━━
🔑 踊場（令24条）
━━━━━━━━━━━━━━━━━━━━━━
・小中高の児童生徒用の階段、および劇場等・大規模物販店舗の客用の階段：高さ3メートル以内ごとに踊場を設ける★
・その他の階段：高さ4メートル以内ごとに踊場を設ける★
・直階段の踊場の踏幅は1.2メートル以上とする★

━━━━━━━━━━━━━━━━━━━━━━
🔑 手すり等（令25条）
━━━━━━━━━━━━━━━━━━━━━━
・階段には手すりを設けなければならない★
・階段およびその踊場の両側（手すりが設けられた側を除く）には、側壁またはこれに代わるものを設ける
・階段の幅が3メートルを超える場合は、中間に手すりを設ける。ただし、蹴上げが15センチメートル以下で、かつ踏面が30センチメートル以上のものは、この限りでない★
・高さ1メートル以下の階段の部分には、これらの規定は適用しない★
⇒ 「高さ1メートル以下の階段には手すり不要」は毎年のように問われます。

【図解】階段の寸法（抜粋）
　区分｜幅｜蹴上げと踏面
　小中高の児童生徒用｜140センチメートル以上★｜16以下と26以上
　劇場客用・大規模物販客用｜140センチメートル以上★｜18以下と26以上
　住宅（共用階段を除く）｜75センチメートル以上★｜23以下と15以上
　⚠ 単位はセンチメートル。共同住宅の共用階段は住宅の欄を使えない。

■ 頻出ひっかけ・本試験での問われ方
・「共同住宅の共用階段は蹴上げ23センチメートル以下、踏面15センチメートル以上でよい」→ ×。住宅の欄から除かれます。
・「階段の幅は手すりの出幅をすべて差し引いて算定する」→ ×。10センチメートルを限度にないものとみなします。
・「高さ1.5メートルの階段には手すりは不要」→ ×。1メートルを超えるので必要です。
・「回り階段の踏面は最も狭い部分で測る」→ ×。狭いほうの端から30センチメートルの位置です。
・「すべての階段は高さ4メートル以内ごとに踊場が必要」→ ×。小中高と劇場等の客用は3メートル以内ごとです。

★ここだけ暗記
・小中高の児童生徒用と劇場等・1500平方メートル超物販の客用は幅140センチメートル、踏面26センチメートル以上。
・住宅は幅75、蹴上げ23、踏面15。共用階段は除く。
・踊場は原則4メートル以内ごと、小中高と客用は3メートル以内ごと、直階段の踏幅1.2メートル以上。
・手すりは高さ1メートル超の階段に必要。幅3メートル超は中間手すり。`,
