        body: `▼ゼロから：防火区画は、建物の中を耐火性のある床・壁と防火設備で細かく仕切って、火と煙を一つの区画に閉じ込める仕組みです。閉じ込めれば燃え広がらず、区画の外の人は落ち着いて逃げられます。令112条は建築基準法施行令の中でも最長クラスの条文で、面積区画、高層区画、竪穴区画、異種用途区画の四種類が入っています。まずは面積区画です。「一定面積ごとに区切る」という単純な発想ですが、対象となる建築物、区画の面積、区画に使う部材、そして免除規定を正確に読む必要があります。スプリンクラーを設ければ面積が倍になる、という緩和も実務で多用されます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 1500平方メートル区画（令112条1項）
━━━━━━━━━━━━━━━━━━━━━━
・対象：主要構造部を耐火構造とした建築物、法2条9号の3イまたはロに該当する準耐火建築物、法27条・法61条により準耐火建築物等としたもの等で、延べ面積が1500平方メートルを超えるもの
・床面積1500平方メートル以内ごとに、1時間準耐火基準に適合する準耐火構造の床もしくは壁、または特定防火設備で区画する★
・スプリンクラー設備、水噴霧消火設備、泡消火設備その他これらに類する自動式の消火設備を設けた部分は、その床面積の2分の1に相当する床面積を除いて算定する★（実質、区画面積が倍になる）

━━━━━━━━━━━━━━━━━━━━━━
🔑 500平方メートル区画と1000平方メートル区画
━━━━━━━━━━━━━━━━━━━━━━
・500平方メートル区画（令112条4項）：法21条1項の規定により主要構造部を一定の性能とした建築物などで、床面積500平方メートル以内ごとに1時間準耐火基準の準耐火構造の床・壁または特定防火設備で区画。
・1000平方メートル区画（令112条5項）：法27条3項、法61条等により準耐火建築物等とした建築物で、床面積1000平方メートル以内ごとに区画。
⇒ 対象がどの条文由来かで面積が変わります。試験では「延べ面積1500平方メートルを超える耐火建築物は1500平方メートル以内ごと」が中心に問われます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 面積区画の免除（令112条1項ただし書）
━━━━━━━━━━━━━━━━━━━━━━
次の用途に供する部分でその用途上やむを得ない場合は、面積区画が免除されます。
・劇場、映画館、演芸場、観覧場、公会堂、集会場の客席、体育館、工場その他これらに類する用途に供する建築物の部分★
・階段室の部分、昇降機の昇降路の部分（乗降ロビーを含む）で1時間準耐火基準の準耐火構造の床・壁または特定防火設備で区画されたもの
⇒ 体育館の中に防火シャッターを下ろすと競技ができないので免除される、と理解すれば覚えやすいです。ただし免除には内装等の条件が付く場合があります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 区画に用いる部材
━━━━━━━━━━━━━━━━━━━━━━
・床・壁：1時間準耐火基準に適合する準耐火構造★
・開口部：特定防火設備（60分の遮炎性能）★。常時閉鎖式または煙感知器連動の随時閉鎖式で、遮煙性能を有するもの（令112条19項1号）
・区画する床または壁が外壁に接する部分：外壁面から50センチメートル以上突出させるか、外壁のうち区画に接する部分を含み幅90センチメートル以上を準耐火構造とする（令112条16項）★
・区画する部分の外壁の開口部が上下に近接する場合は、90センチメートル以上離すか、ひさし等を50センチメートル以上突出させる（スパンドレル）★

【図解】面積区画の面積
　対象｜区画面積｜開口部
　耐火建築物・イロ準耐で延べ1500平方メートル超｜1500平方メートル以内ごと★｜特定防火設備
　法21条関係｜500平方メートル以内ごと｜特定防火設備
　法27条3項・法61条関係｜1000平方メートル以内ごと｜特定防火設備
　⚠ 自動式消火設備を設けた部分は床面積の2分の1を除いて算定できる。

■ 頻出ひっかけ・本試験での問われ方
・「面積区画の開口部には防火設備を用いればよい」→ ×。特定防火設備です。
・「スプリンクラーを設けた部分は面積区画が全部免除される」→ ×。床面積の2分の1を除いて算定するだけです。
・「体育館は延べ面積が1500平方メートルを超えても面積区画が不要である」→ その用途上やむを得ない場合に限られるので、条件を確認します。
・「スパンドレルの高さは50センチメートル以上」→ ×。上下の開口部の距離は90センチメートル以上、ひさし等の突出は50センチメートル以上です。
・引くところ：令112条1項から5項、16項、19項。

★ここだけ暗記
・原則は1500平方メートル以内ごと、1時間準耐火基準の床壁と特定防火設備。
・自動式消火設備がある部分は床面積の2分の1を除いて算定。
・免除は劇場等の客席、体育館、工場など用途上やむを得ない場合。
・スパンドレルは突出50センチメートル以上、上下の開口部の離隔90センチメートル以上。`,
