        id: 'nk-ho-22', title: '防火区画③竪穴区画', emoji: '🕳️',
        body: `▼ゼロから：火災で人が亡くなる最大の原因は煙です。煙は上へ上へと昇るので、階段や吹抜けのような縦につながった空間があると、そこが煙突になって一気に上階へ煙を運びます。これを防ぐのが竪穴区画です。令112条11項は、主要構造部を準耐火構造とし、地階または3階以上の階に居室を有する建築物について、階段、吹抜け、エレベーターの昇降路、ダクトスペースなどの竪穴部分を、その他の部分と区画せよと定めています。試験では「どの建物が対象か」「何で区画するか」「どんなときに免除されるか」の三点が問われます。特に対象要件の読み方は毎年のように狙われます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 竪穴区画の対象（令112条11項）
━━━━━━━━━━━━━━━━━━━━━━
・主要構造部を準耐火構造とし、かつ地階または3階以上の階に居室を有する建築物★
・区画する部分：吹抜けとなっている部分、階段の部分（避難階段・特別避難階段を含む）、昇降機の昇降路の部分、ダクトスペースの部分その他これらに類する部分
・区画の方法：準耐火構造の床もしくは壁、または法2条9号の2ロに規定する防火設備で区画する★
⇒ 開口部は「防火設備」でよく、特定防火設備までは要りません。ただし遮煙性能を有するもの（令112条19項2号）が必要です★

━━━━━━━━━━━━━━━━━━━━━━
🔑 3階を特定の用途に供する場合（令112条12項・13項）
━━━━━━━━━━━━━━━━━━━━━━
・3階を病院、診療所（患者の収容施設があるもの）、児童福祉施設等の用途に供する建築物で、階数3かつ延べ面積200平方メートル未満のものは、竪穴部分と他の部分とを間仕切壁または戸（ふすま・障子等を除く）で区画すればよい★
・3階を法別表第一(い)欄(2)項に掲げる用途（ホテル、旅館、下宿、共同住宅、寄宿舎等）に供する建築物で、階数3かつ延べ面積200平方メートル未満のものも同様の扱い。
⇒ 小規模な3階建ての福祉施設や下宿を建てやすくするための規定です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 竪穴区画の免除（令112条11項ただし書）
━━━━━━━━━━━━━━━━━━━━━━
・避難階からその直上階または直下階のみに通ずる吹抜けとなっている部分等で、その部分の壁および天井の室内に面する部分の仕上げを不燃材料でし、かつ下地を不燃材料で造ったもの★
・階数が3以下で延べ面積が200平方メートル以内の一戸建ての住宅、または長屋・共同住宅の住戸★
⇒ 一般的な木造3階建て住宅の階段に防火戸が要らないのは、この免除によります。ただし延べ面積200平方メートルを超えると必要になります。ここは実務でも試験でも重要です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 竪穴区画で押さえる細部
━━━━━━━━━━━━━━━━━━━━━━
・区画に用いる防火設備は、常時閉鎖式または随時閉鎖式で、煙感知器連動により閉鎖するもの★
・エレベーターの乗降ロビーは昇降路の一部として区画対象です。
・住戸内の階段（メゾネット型住戸の内部階段）は、住戸が竪穴区画の一区画とされていれば、その内部でさらに区画する必要はありません。
・区画された竪穴部分の壁が外壁に接する部分には、スパンドレル（令112条16項）が必要です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 竪穴区画の設計上の要点
━━━━━━━━━━━━━━━━━━━━━━
・階段室を区画する場合、階段室の入口に防火設備（常時閉鎖式の戸または煙感知器連動の自動閉鎖式の戸）を設けます。日常の使い勝手を考えて、常時開放で煙感知器連動とするのが一般的です。
・吹抜けを設けたい住宅では、延べ面積を200平方メートル以内に抑えるか、吹抜けを避難階とその直上階または直下階だけにとどめ、内装を不燃材料とする方法があります★
・エレベーターの乗降ロビーを区画する場合、共用廊下との間に防火設備が必要になります。
・ダクトスペースやパイプシャフトも竪穴なので、各階の床で区画するか、シャフト自体を準耐火構造の壁で囲みます。
・竪穴区画は面積区画・高層区画・異種用途区画と重ねてかかります。どれか一つを満たせば他が免除されるわけではありません★
⇒ 実務では、平面図に区画線を書き込み、扉の種類を記号で示す「防火区画図」を作成して整理します。

【図解】竪穴区画の要否
　建築物｜竪穴区画｜根拠
　主要構造部が準耐火構造で3階に居室あり、延べ300平方メートル｜必要★｜令112条11項
　階数3で延べ面積180平方メートルの一戸建て住宅｜不要★｜11項ただし書
　主要構造部が木造で防火措置のない2階建て住宅｜不要｜対象外
　⚠ 開口部は防火設備でよいが、遮煙性能と煙感知器連動が必要。

■ 頻出ひっかけ・本試験での問われ方
・「竪穴区画の開口部には特定防火設備が必要」→ ×。防火設備で足ります。
・「2階建ての建築物にも竪穴区画が必要」→ ×。地階または3階以上の階に居室があることが要件です。
・「延べ面積250平方メートルの3階建て一戸建て住宅は竪穴区画が不要」→ ×。200平方メートル以内が条件です。
・「エレベーターの昇降路は竪穴区画の対象外」→ ×。対象です。
・引くところ：令112条11項から13項、19項2号。

★ここだけ暗記
・対象は主要構造部が準耐火構造で、地階または3階以上に居室を有する建築物。
・区画は準耐火構造の床壁または防火設備。遮煙性能と煙感知器連動。
・階数3以下かつ延べ面積200平方メートル以内の一戸建て住宅・住戸は免除。
・避難階と直上階または直下階のみの吹抜けで内装不燃なら免除。`,
