        body: `▼ゼロから：構造計算が不要な小規模建築物でも、令第3章の仕様規定はかならず守らなければなりません。仕様規定とは「この寸法以上にせよ」「この金物を使え」という具体的な作り方の決まりで、計算をしなくても最低限の安全を確保するための知恵です。一方、構造計算をするときには、まず建物にかかる力を決めなければなりません。それが荷重と外力で、令83条から令88条にまとまっています。固定荷重、積載荷重、積雪荷重、風圧力、地震力の五つです。法規の試験では、積載荷重の表の使い分けと、地震力の標準せん断力係数0.2という数値がよく問われます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 仕様規定の全体像（令第3章）
━━━━━━━━━━━━━━━━━━━━━━
・第1節 総則（令36条から令36条の3）：構造方法に関する技術的基準、構造設計の原則
・第2節 構造部材等（令37条から令39条）：材料の耐久性、基礎、屋根ふき材等
・第3節 木造（令40条から令50条）
・第4節 組積造（令51条から令62条）
・第4節の2 補強コンクリートブロック造（令62条の2から令62条の8）
・第5節 鉄骨造（令63条から令70条）
・第6節 鉄筋コンクリート造（令71条から令79条）
・第6節の2 鉄骨鉄筋コンクリート造（令79条の2から令79条の4）
・第7節 無筋コンクリート造（令80条）
・第8節 構造計算（令81条から令99条）
⇒ 法令集の背表紙側にインデックスを貼って、節ごとに一発で開けるようにしておきます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 固定荷重と積載荷重（令84条・令85条）
━━━━━━━━━━━━━━━━━━━━━━
・固定荷重は、建築物の実況に応じて計算するか、令84条の表の数値によります。
・積載荷重は、実況に応じて計算するか、令85条の表の数値によります。表は用途ごとに三つの欄に分かれます★
　一の欄：床の構造計算をする場合
　二の欄：大ばり、柱または基礎の構造計算をする場合
　三の欄：地震力を計算する場合
・数値の例（単位はニュートン毎平方メートル）
　住宅の居室、住宅以外の建築物における寝室または病室：1800／1300／600★
　事務室：2900／1800／800★
　教室：2300／2100／1100
　百貨店または店舗の売場：2900／2400／1300
　劇場等の客席で固定席のもの：2900／2600／1600
・一の欄が最も大きく、三の欄が最も小さいのが原則です★。柱や基礎は多くの床を支えるため平均化され、地震力は建物全体の質量を扱うためさらに小さくなります。
・倉庫業を営む倉庫の床の積載荷重は、実況によらず3900ニュートン毎平方メートル以上とします★

━━━━━━━━━━━━━━━━━━━━━━
🔑 積雪荷重（令86条）
━━━━━━━━━━━━━━━━━━━━━━
・積雪の単位荷重は、積雪量1センチメートルごとに1平方メートルにつき20ニュートン以上とする（多雪区域を除く）★
・垂直積雪量は、特定行政庁が規則で定めます。
・屋根の積雪荷重は、屋根の勾配が60度を超える場合は屋根形状係数により低減でき、60度を超えると0とすることができる★
・雪止めがなく勾配が緩やかでない屋根については、実況に応じた低減が認められる場合があります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 風圧力と地震力（令87条・令88条）
━━━━━━━━━━━━━━━━━━━━━━
・風圧力 ＝ 速度圧 × 風力係数
　速度圧 q ＝ 0.6 × E × Vo の2乗（Eは屋根の高さと周辺の地表面粗度区分による数値、Voはその地方の基準風速で毎秒30メートルから46メートル）★
・地震力（地上部分）：各階に作用する地震力は、その階が支える重量に地震層せん断力係数Ciを乗じて求めます。
　Ci ＝ Z × Rt × Ai × Co
　Zは地震地域係数、Rtは振動特性係数、Aiは高さ方向の分布係数、Coは標準せん断力係数
・標準せん断力係数Coは0.2以上★。必要保有水平耐力を計算する場合は1.0以上★
・木造建築物で地盤が著しく軟弱な区域として特定行政庁が指定する区域内では、Coは0.3以上★
・地下部分の地震力は、水平震度k（k は0.1×(1 − H/40)×Z 以上、Hは地盤面からの深さで20メートルを超えるときは20）を用います★

【図解】積載荷重の三つの欄（単位はニュートン毎平方メートル）
　用途｜床用｜地震力用
　住宅の居室｜1800★｜600★
　事務室｜2900★｜800★
　百貨店の売場｜2900｜1300
　⚠ 床用が最大、地震力用が最小。倉庫業の倉庫の床は3900以上。

■ 頻出ひっかけ・本試験での問われ方
・「積載荷重は床用より地震力用のほうが大きい」→ ×。床用が最大です。
・「標準せん断力係数は0.1以上」→ ×。0.2以上です。
・「積雪の単位荷重は1センチメートルにつき10ニュートン以上」→ ×。20ニュートン以上です。
・「屋根の勾配が45度を超えると積雪荷重は0とできる」→ ×。60度を超える場合です。
・「事務室の床の積載荷重は住宅の居室より小さい」→ ×。事務室2900、住宅1800で事務室が大きい。

★ここだけ暗記
・積載荷重は床用・大ばり柱基礎用・地震力用の三欄。住宅1800／1300／600、事務室2900／1800／800。
・積雪は1センチメートルにつき20ニュートン以上、勾配60度超で0にできる。
・地震力のCoは0.2以上、保有水平耐力計算では1.0以上、軟弱地盤の木造は0.3以上。
・倉庫業を営む倉庫の床は3900ニュートン毎平方メートル以上。`,
