        body: `▼ゼロから：用途地域は13種類しかないので、実際のまちの事情をすべて表現できません。そこで、用途地域に重ねて指定して規制を上乗せしたり緩めたりする仕組みが用意されています。特別用途地区、特定用途制限地域、高層住居誘導地区、特例容積率適用地区、高度利用地区、防火地域・準防火地域、風致地区などです。これらは都市計画法で定められ、建築基準法が具体的な制限を書くという役割分担になっています。二級の試験ではそれぞれの制度の目的と、条例で定めるのか都市計画で定めるのかという手続が問われます。田園住居地域の農地の規制もここで扱います。

━━━━━━━━━━━━━━━━━━━━━━
🔑 特別用途地区（法49条）
━━━━━━━━━━━━━━━━━━━━━━
・用途地域内の一定の地区における当該地区の特性にふさわしい土地利用の増進、環境の保護等の特別の目的の実現を図るため、用途地域の指定を補完して定める地区です（都市計画法9条14項）。
・特別用途地区内においては、その地区の指定の目的のためにする建築物の建築の制限または禁止に関して必要な規定は、地方公共団体の条例で定める★
・地方公共団体は、国土交通大臣の承認を得て、条例で法48条の制限を緩和することができる★
⇒ 文教地区、特別工業地区、観光地区などが代表例です。制限の付加も緩和も条例で行う点が特徴です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 特定用途制限地域（法49条の2）
━━━━━━━━━━━━━━━━━━━━━━
・用途地域が定められていない土地の区域（市街化調整区域を除く）内において、その良好な環境の形成または保持のため、当該地域の特性に応じて合理的な土地利用が行われるよう、制限すべき特定の建築物等の用途の概要を定める地域★
・当該地域内における建築物の用途の制限は、地方公共団体の条例で定める★
⇒ 用途地域がない非線引き都市計画区域や準都市計画区域で使われます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 田園住居地域の特則（法52条、都市計画法）
━━━━━━━━━━━━━━━━━━━━━━
・平成30年に創設された13番目の用途地域で、都市部に残る農地と低層住宅を共存させる目的があります。
・建築できるもの：低層住宅、農産物直売所、農家レストラン（500平方メートル以内）、農産物の生産・集荷・処理・貯蔵に供するもの、農業の生産資材の貯蔵に供するものなど★
・絶対高さ制限（10メートルまたは12メートル）、外壁の後退距離、北側斜線制限は第一種・第二種低層住居専用地域と同様に適用される★
・田園住居地域内の農地の区域内で、土地の形質の変更、建築物の建築、土石等の堆積を行う場合は、市町村長の許可が必要（都市計画法52条）★

━━━━━━━━━━━━━━━━━━━━━━
🔑 その他の主な地域地区
━━━━━━━━━━━━━━━━━━━━━━
・高層住居誘導地区（法57条の2ほか）：住居と住居以外の用途を適正に配分し、利便性の高い高層住宅の建設を誘導する。容積率の最高限度が10分の40または10分の50と定められた第一種住居地域、第二種住居地域、準住居地域、近隣商業地域、準工業地域内で定められる★
・特例容積率適用地区（法57条の2）：複数の敷地間で未利用の容積率を移転できる制度。
・高度利用地区（法59条）：容積率の最高限度・最低限度、建蔽率の最高限度、建築面積の最低限度、壁面の位置の制限を定める。市街地の再開発に用いられる★
・高度地区（法58条）：建築物の高さの最高限度または最低限度を都市計画で定める★
・特定街区（法60条）：容積率、高さの最高限度、壁面の位置の制限を都市計画で定め、法52条等の規定を適用しない。
・風致地区（都市計画法58条）：都市の風致を維持するため、条例で建築物の建築等を規制する。
・景観地区（景観法）：建築物の形態意匠の制限、高さの最高限度・最低限度、壁面の位置の制限、敷地面積の最低限度を定める。

【図解】制限を定める方法の違い
　制度｜制限を定めるもの｜特徴
　特別用途地区｜地方公共団体の条例★｜大臣承認で緩和も可能★
　特定用途制限地域｜地方公共団体の条例★｜用途地域のない区域が対象
　高度地区・高度利用地区｜都市計画★｜数値を都市計画で定める
　⚠ 田園住居地域内の農地では土地の形質変更等に市町村長の許可が必要。

■ 頻出ひっかけ・本試験での問われ方
・「特別用途地区の制限は都市計画で定める」→ ×。地方公共団体の条例で定めます。
・「特定用途制限地域は市街化調整区域にも定められる」→ ×。除かれます。
・「高度地区では容積率の最高限度を定める」→ ×。高さの最高限度または最低限度です。容積率は高度利用地区。
・「田園住居地域には絶対高さ制限は適用されない」→ ×。10メートルまたは12メートルが適用されます。
・「特別用途地区では条例による制限の緩和はできない」→ ×。国土交通大臣の承認を得れば可能です。

★ここだけ暗記
・特別用途地区と特定用途制限地域は条例で制限。特別用途地区は大臣承認で緩和も可。
・高度地区は高さ、高度利用地区は容積率と建蔽率と建築面積と壁面位置。
・田園住居地域は低層住居専用地域と同じ高さ制限、農地の形質変更等は市町村長の許可。
・高層住居誘導地区は容積率10分の40または10分の50の一定地域で指定。`,
