・特定街区（法60条）：容積率、建築物の高さの最高限度、壁面の位置の制限を都市計画で定め、その街区については法52条（容積率）、法53条（建蔽率）、法55条から法57条（高さ関係）、法58条、法59条等の規定を適用しない★
・総合設計制度（法59条の2）：敷地内に一定規模以上の空地を有し、かつ敷地面積が一定規模以上である建築物で、特定行政庁が交通上、安全上、防火上および衛生上支障がなく、市街地の環境の整備改善に資すると認めて許可したものについては、容積率または各部分の高さの制限を緩和できる★。許可には建築審査会の同意が必要です。

━━━━━━━━━━━━━━━━━━━━━━
