・工事監理の終了時の報告（士法20条3項）：建築士は、工事監理を終了したときは、直ちに、その結果を文書で建築主に報告しなければならない★
・設計図書への記名（士法20条1項）：建築士は、設計を行った場合においては、その設計図書に一級建築士、二級建築士または木造建築士である旨の表示をして記名しなければならない。設計図書の一部を変更した場合も同様★
・他人の設計した設計図書の変更（士法19条）：建築士は、他の建築士の設計した設計図書の一部を変更しようとするときは、当該建築士の承諾を求めなければならない。ただし、承諾を求めることのできない事由があるとき、または承諾が得られなかったときは、自己の責任において変更することができる★
・名義貸しの禁止（士法21条の2）：建築士は、他人に自己の名義を利用させてはならない★
・違反行為の指示等の禁止（士法21条の3）、信用失墜行為の禁止（士法21条の4）★

