★ここだけ暗記
・事務所登録は都道府県知事、有効期間5年。管理建築士は実務3年以上と講習修了。
・重要事項説明は契約前に管理建築士等が書面を交付して説明し、免許証を提示。
・帳簿と設計図書は15年保存。標識の掲示と書類の閲覧。
