・区域区分（線引き）：無秩序な市街化を防止し、計画的な市街化を図るため必要があるときは、都市計画に市街化区域と市街化調整区域との区分を定めることができる★
　市街化区域：すでに市街地を形成している区域、およびおおむね10年以内に優先的かつ計画的に市街化を図るべき区域★
　市街化調整区域：市街化を抑制すべき区域★
・市街化区域については少なくとも用途地域を定め、市街化調整区域については原則として用途地域を定めない★
・準都市計画区域：都市計画区域外で、そのまま土地利用を整序しないと将来の都市としての整備に支障が生じるおそれがある区域について、都道府県が指定する★

