━━━━━━━━━━━━━━━━━━━━━━
・開発行為＝主として建築物の建築または特定工作物の建設の用に供する目的で行う土地の区画形質の変更★
・開発許可が必要な規模
　市街化区域：1000平方メートル以上★（三大都市圏の一定の区域では500平方メートル以上）
　市街化調整区域：規模にかかわらず許可が必要★
　非線引き都市計画区域および準都市計画区域：3000平方メートル以上★
　都市計画区域および準都市計画区域外：1ヘクタール（10000平方メートル）以上★
