━━━━━━━━━━━━━━━━━━━━━━
・市街化調整区域、非線引き都市計画区域または準都市計画区域内において行う開発行為で、農業、林業もしくは漁業の用に供する政令で定める建築物、またはこれらの業務を営む者の居住の用に供する建築物の建築の用に供する目的で行うもの★（市街化区域では適用されない点に注意）
