        body: `▼ゼロから：この二つは、既存の建物や新築の建物に社会的な要請を反映させる法律です。バリアフリー法（高齢者、障害者等の移動等の円滑化の促進に関する法律）は、誰もが使える建物にするための基準を定め、一定規模以上の建築行為に適合を義務づけます。耐震改修促進法は、旧耐震基準で建てられた建物の耐震診断と改修を促す法律です。どちらも「義務がかかる範囲」と「認定を受けると得られる特例」という構造を持っています。試験では、特別特定建築物の2000平方メートルという数値と、耐震改修計画の認定による建築基準法の特例が問われます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 バリアフリー法の対象建築物
━━━━━━━━━━━━━━━━━━━━━━
・特定建築物：学校、病院、劇場、観覧場、集会場、展示場、百貨店、ホテル、事務所、共同住宅、老人ホームその他の多数の者が利用する建築物。建築物移動等円滑化基準への適合は努力義務★
・特別特定建築物：特定建築物のうち、不特定かつ多数の者が利用し、または主として高齢者、障害者等が利用するもの。病院、劇場、集会場、百貨店、ホテル、老人ホーム、保健所、公衆浴場、飲食店、公共交通機関の施設、公立小中学校など★
・共同住宅と事務所は特定建築物であって特別特定建築物ではありません★

━━━━━━━━━━━━━━━━━━━━━━
🔑 適合義務（バリアフリー法14条）
━━━━━━━━━━━━━━━━━━━━━━
・建築主等は、特別特定建築物の政令で定める規模（床面積の合計2000平方メートル以上、公衆便所は50平方メートル以上）以上の建築（新築、増築、改築、用途変更）をしようとするときは、建築物移動等円滑化基準に適合させなければならない★
・地方公共団体は、条例で、特定建築物を特別特定建築物に追加したり、規模を引き下げたり、基準を付加したりできる★
・建築物移動等円滑化基準への適合は、建築基準関係規定とみなされ、建築確認の審査対象となります★

━━━━━━━━━━━━━━━━━━━━━━
🔑 認定と誘導基準
━━━━━━━━━━━━━━━━━━━━━━
・建築主等は、特定建築物の建築等および維持保全の計画を作成し、所管行政庁の認定を申請することができる（バリアフリー法17条）★
・認定の基準は建築物移動等円滑化誘導基準で、義務基準より高い水準です。
・認定を受けた特定建築物（認定特定建築物）には、廊下、階段、便所等のうち移動等円滑化の措置がとられた部分について、容積率の算定における延べ面積の特例（一定割合を限度に不算入）があります★
・認定特定建築物には、その旨の表示（認定マーク）をすることができます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 耐震改修促進法
━━━━━━━━━━━━━━━━━━━━━━
・要安全確認計画記載建築物：都道府県または市町村が耐震改修促進計画に記載した避難路沿道建築物や防災拠点建築物。所有者は耐震診断を行い、期限までに結果を所管行政庁に報告しなければならない★
・要緊急安全確認大規模建築物：不特定多数が利用する大規模建築物等で、耐震診断の実施と結果の報告が義務づけられたもの★
・特定既存耐震不適格建築物：学校、病院、劇場、百貨店、ホテル等で一定規模以上のもの、および一定の危険物の貯蔵場等。所有者は耐震診断と必要な改修を行うよう努めなければならない（努力義務）。所管行政庁は指導・助言、指示、公表ができる★
・建築物の耐震改修の計画の認定（法17条）：所管行政庁の認定を受けた耐震改修の計画については、建築基準法の確認済証の交付があったものとみなされるほか、耐火建築物に関する規定、容積率・建蔽率の制限について特例が受けられる★
・区分所有建築物の耐震改修の必要性に係る認定を受けた場合、耐震改修の決議は区分所有者および議決権の各過半数で足りる★
・建築物の地震に対する安全性に係る認定（法22条）：基準に適合すると認定された建築物には、その旨の表示ができる★

【図解】バリアフリー法と耐震改修促進法
　項目｜内容｜備考
　特別特定建築物の義務規模｜2000平方メートル以上★｜公衆便所は50平方メートル以上
　特定建築物｜努力義務★｜共同住宅・事務所は特定建築物
　耐震改修計画の認定｜確認済証の交付とみなす★｜容積率等の特例
　⚠ 条例で対象や規模を上乗せできるが緩和はできない。

■ 頻出ひっかけ・本試験での問われ方
・「共同住宅は特別特定建築物である」→ ×。特定建築物です。
・「特別特定建築物の適合義務は床面積1000平方メートル以上でかかる」→ ×。2000平方メートル以上です。
・「地方公共団体は条例で対象規模を引き上げることができる」→ ×。引き下げ（対象を広げる方向）ができます。
・「耐震改修計画の認定を受けても建築確認は別途必要」→ ×。確認済証の交付があったものとみなされます。
・「特定既存耐震不適格建築物の耐震診断は義務である」→ ×。原則は努力義務です（要安全確認計画記載建築物等は義務）。

★ここだけ暗記
・特別特定建築物は2000平方メートル以上で適合義務、公衆便所は50平方メートル以上。
・共同住宅と事務所は特定建築物で努力義務。条例で上乗せ可。
・認定特定建築物は誘導基準に適合し、容積率の特例がある。
・耐震改修計画の認定で確認済証の交付とみなされ、区分所有建築物の決議は各過半数。`,
