・建築主は、特定建築行為をしようとするときは、所管行政庁または登録建築物エネルギー消費性能判定機関の建築物エネルギー消費性能適合性判定を受けなければならない★
・適合性判定を受けた場合、建築主事等に適合判定通知書を提出しなければ、確認済証の交付を受けられません★
・小規模な建築物については、仕様基準や標準的な計算方法（モデル建物法、住宅ではモデル住宅法や仕様基準）を用いた簡易な評価が認められています★

━━━━━━━━━━━━━━━━━━━━━━
