━━━━━━━━━━━━━━━━━━━━━━
・新築住宅の売主である宅地建物取引業者、および請負人である建設業者は、瑕疵担保責任を確実に履行するため、住宅販売瑕疵担保保証金の供託または住宅瑕疵担保責任保険への加入が義務づけられる★
・資力確保措置の状況は、基準日（毎年3月31日）ごとに、免許権者または許可権者に届け出なければならない★
・届出をしないと、基準日の翌日から起算して50日を経過した日以後、新たに新築住宅の売買契約または請負契約を締結できなくなる★
・保険金額は1戸あたり2000万円以上、保険期間は引渡しから10年以上★

